(6087099, 896121, 116354, '<td valign="top">Nice and elegant; I like the compression that comes with your choice of the focal length, and the overall softness of the image. Not a big fan of the frame.</td>', 'Nice and elegant; I like the compression that comes with your choice of the focal length, and the overall softness of the image. Not a big fan of the frame.', '2010-07-10 01:29:29.000000', NULL, 1),
(6087103, 896139, 116354, '<td valign="top">This is technically very well-executed image, though I find it very hard to _really_ like this. Perhaps this comes from that we have seen the likes of this composition many times before. I would prefer deeper DOF, and maybe less aggressive focal-length.</td>', 'This is technically very well-executed image, though I find it very hard to _really_ like this. Perhaps this comes from that we have seen the likes of this composition many times before. I would prefer deeper DOF, and maybe less aggressive focal-length.', '2010-07-10 01:34:44.000000', NULL, 1),
(6087105, 895494, 116354, '<td valign="top">I like the idea here. Personally I would prefer more precision geometrically. At the moment there is a slight horizontal tilt in the composition..</td>', 'I like the idea here. Personally I would prefer more precision geometrically. At the moment there is a slight horizontal tilt in the composition..', '2010-07-10 01:36:31.000000', NULL, 1),
(6087146, 894886, 83313, '<td valign="top">Now he just needs some of the orange Hot Wheels tracks that can be routed all over the house. Lots of fun. Extra pointage for the blast from the past.</td>', 'Now he just needs some of the orange Hot Wheels tracks that can be routed all over the house. Lots of fun. Extra pointage for the blast from the past.', '2010-07-10 02:56:19.000000', NULL, 1),
(6087337, 896074, 118447, '<td valign="top">I agree...Very sweet</td>', 'I agree...Very sweet', '2010-07-10 11:59:22.000000', NULL, 1),
(6087418, 895714, 110202, '<td valign="top">very moving</td>', 'very moving', '2010-07-10 13:37:12.000000', NULL, 1),
(6087483, 894906, 33781, '<td valign="top">Great composition. Did you use graduated ND filter or polarizer filter?</td>', 'Great composition. Did you use graduated ND filter or polarizer filter?', '2010-07-10 16:08:03.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6087484, 896048, 33781, '<td valign="top">Well timed and unique compositions. Love it.</td>', 'Well timed and unique compositions. Love it.', '2010-07-10 16:08:25.000000', NULL, 1),
(6087536, 896029, 59633, '<td valign="top">Absolutely fabulous!</td>', 'Absolutely fabulous!', '2010-07-10 17:25:52.000000', NULL, 1),
(6087673, 896152, 63398, '<td valign="top">You''re freakin'' NUTS!!! LOL!!! 10</td>', 'You''re freakin'' NUTS!!! LOL!!! 10', '2010-07-10 21:12:28.000000', NULL, 1),
(6088085, 895729, 117474, '<td valign="top">Nice idea. Simple and effective. I think it''ll do well. <br/>It''d''ve been nice if you could have narrowed the DOF to make the letters on front and behind the "ORDER" go blurry - I think opening your aperture (by lowering the aperture number) and maybe a narrower angle might have made this work. <br/>It might be nice too if the image was cropped equally on the right and left. Equally a tighter crop on the left would achieve the same. <br/>"in the midst of chaos" Something just came to me there. The chaos might have been provoked more with a grainy feel over the image. Maybe not. Might be worth trying out. <br/> <br/>Phfew. long comment :)</td>', 'Nice idea. Simple and effective. I think it''ll do well. It''d''ve been nice if you could have narrowed the DOF to make the letters on front and behind the "ORDER" go blurry - I think opening your aperture (by lowering the aperture number) and maybe a narrower angle might have made this work. It might be nice too if the image was cropped equally on the right and left. Equally a tighter crop on the left would achieve the same. "in the midst of chaos" Something just came to me there. The chaos might have been provoked more with a grainy feel over the image. Maybe not. Might be worth trying out.  Phfew. long comment :)', '2010-07-11 11:41:44.000000', NULL, 1),
(6088086, 894696, 117474, '<td valign="top">I did some reading on the colours of the rainbow just now, and <a href="//en.wikipedia.org/wiki/Rainbow#Distinct_colours" rel="nofollow" target="_blank">wikipedia</a>, at any rate, seems to give 7 colours in the spectrum. It''s a big debate, I think, and I''m far from an expert in that field, so I can''t justify using that as an excuse to take marks off. <br/> <br/>Yours is an excellently composed image. I like the background and the lighting (and I''ve no idea how you did it!). <br/>My only problem with it is that as the colours narrow at the bottom the... vibrancy of the colours appears to diminish. This might have been intentional but I think I''d''ve preferred a continuous strength.<br/>You gonna tell us how you did this? :)<br/>9</td>', 'I did some reading on the colours of the rainbow just now, and wikipedia, at any rate, seems to give 7 colours in the spectrum. It''s a big debate, I think, and I''m far from an expert in that field, so I can''t justify using that as an excuse to take marks off.  Yours is an excellently composed image. I like the background and the lighting (and I''ve no idea how you did it!). My only problem with it is that as the colours narrow at the bottom the... vibrancy of the colours appears to diminish. This might have been intentional but I think I''d''ve preferred a continuous strength.You gonna tell us how you did this? :)9', '2010-07-11 11:41:49.000000', NULL, 1),
(6088090, 896048, 117474, '<td valign="top">That''s a superb catch!</td>', 'That''s a superb catch!', '2010-07-11 11:43:42.000000', NULL, 1),
(6088091, 895239, 117474, '<td valign="top">Very nice lighting. <br/>And the boarder works well too.</td>', 'Very nice lighting. And the boarder works well too.', '2010-07-11 11:43:52.000000', NULL, 1),
(6088092, 896219, 117474, '<td valign="top">Very nice symmetry here.<br/>I meant to say earlier -- I know it''d be very hard to achieve this, but the green-on-green-ness of this is a bit overpowering. I don''t suppose you''d be able to see the ladder of symmetry with a younger tree though.</td>', 'Very nice symmetry here.I meant to say earlier -- I know it''d be very hard to achieve this, but the green-on-green-ness of this is a bit overpowering. I don''t suppose you''d be able to see the ladder of symmetry with a younger tree though.', '2010-07-11 11:44:01.000000', NULL, 1),
(6088093, 895794, 117474, '<td valign="top">I''m Irish. I''ve totally gotta score this high! <br/>Out of curiosity what was the event that inspred the Irish flags?</td>', 'I''m Irish. I''ve totally gotta score this high! Out of curiosity what was the event that inspred the Irish flags?', '2010-07-11 11:44:04.000000', NULL, 1),
(6088162, 896134, 104009, '<td valign="top">Mise en place!</td>', 'Mise en place!', '2010-07-11 13:31:06.000000', NULL, 1),
