(6089163, 896180, 18207, '<td valign="top">No. Sorry. It''s irrelevant, it looks over-processed, its unclear.</td>', 'No. Sorry. It''s irrelevant, it looks over-processed, its unclear.', '2010-07-12 06:40:39.000000', NULL, 1),
